<?php if($error):?><p class="error" role="alert"><?=h($error)?></p><?php endif;?><div class="two-cols"><form method="post"><?=csrfField()?><input type="hidden" name="id" value="<?=h($row['id']??'')?>"><h2><?=t('Учётная запись менеджера','Manager account')?></h2><label><?=t('Логин','Login')?><input name="login" required pattern="[a-zA-Z0-9_-]{3,60}" maxlength="60" value="<?=h($row['login']??'')?>"></label><label><?=t('Пароль от 8 символов','Password, at least 8 characters')?><input name="password" type="password" minlength="8" maxlength="100" autocomplete="new-password" <?=$row?'':'required'?>></label><?php if($row):?><p class="small"><?=t('Оставьте пароль пустым, чтобы не менять.','Leave password empty to keep it unchanged.')?></p><?php endif;?><label class="check"><input type="checkbox" name="active" value="1" <?=($row['active']??1)?'checked':''?>> <?=t('Активен','Active')?></label><fieldset><legend><?=t('Разрешённые разделы','Allowed sections')?></legend><?php foreach($sections as $key=>$meta):?><label class="check"><input type="checkbox" name="permissions[]" value="<?=$key?>" <?=in_array($key,$permissions,true)?'checked':''?>> <?=h(t($meta['name'],$meta['en']))?></label><?php endforeach;?></fieldset><p><button class="button"><?=t('Сохранить менеджера','Save manager')?></button> <a href="/admin/managers"><?=t('Новый','New')?></a></p></form><div><h2><?=t('Пользователи','Users')?></h2><table><thead><tr><th><?=t('Логин','Login')?></th><th><?=t('Роль','Role')?></th><th><?=t('Активен','Active')?></th></tr></thead><tbody><?php foreach($users as $item):?><tr><td><?php if($item['role']==='manager'):?><a href="/admin/managers?edit=<?=$item['id']?>"><?=h($item['login'])?></a><?php else:?><?=h($item['login'])?><?php endif;?></td><td><?=h($item['role'])?></td><td><?=$item['active']?t('Да','Yes'):t('Нет','No')?></td></tr><?php endforeach;?></tbody></table><p class="small"><?=t('Менеджер видит только разрешённые разделы. Прямые запросы к остальным страницам тоже запрещены.','A manager only sees allowed sections. Direct requests to other sections are denied as well.')?></p></div></div>
